INSERT OR IGNORE INTO covers (id, slug, original_id, cover_id, description, contributor, tags, created_at) VALUES
	(1, 'angel-eyes-the-czars', 1, 2, 'Classic ABBA pop melts into acoustic-led gay heartbreak.', 'Eva', '["energy_down","transition_ftm","valence_down","years_apart_30"]', '2023-10-22T00:40:29.659Z'),
	(2, 'once-in-a-lifetime-angelique-kidjo', 3, 4, 'Incredible, transformative, will make you into a new person.', 'Eva', '["transition_mtf","years_apart_30"]', '2023-10-22T00:56:41.295Z'),
	(3, 'killing-me-softly-luther-vandross', 5, 6, 'I’d let Luther Vandross kill me softly. Phewww.', 'Eva', '["transition_ftm","years_apart_20"]', '2023-10-22T01:29:46.763Z'),
	(4, 'big-in-japan-ane-brun', 7, 8, 'I heard the Ane Brun cover first and fell in love. When I heard the Alphaville it was so different!', 'Eva', '["acousticness_up","tempo_down","transition_mtf","years_apart_20"]', '2023-10-22T02:10:47.803Z'),
	(5, 'cant-get-you-out-of-my-head-the-flaming-lips', 9, 10, 'It''s a dirge. Of Kylie Minogue. As only The Flaming Lips could.', 'Eva', '["tempo_down","transition_ftm","valence_down"]', '2023-10-22T02:20:48.410Z'),
	(6, 'i-cant-get-no-satisfaction-cat-power', 11, 12, 'Stripped down and slowed down. Music that makes you want to smoke a cigarette.', 'Eva', '["acousticness_up","energy_down","transition_mtf","valence_down","years_apart_30"]', '2023-10-22T02:36:07.507Z'),
	(7, 'time-after-time-miles-davis', 13, 14, 'The gender being swapped in here is trumpet.', 'Eva', '[]', '2023-10-22T02:43:31.895Z'),
	(8, 'valerie-amy-winehouse', 15, 16, 'Amy’s version wasn’t the original! The Zutons were just bugging some girl name Valerie.', 'Eva', '["acousticness_up","energy_down","tempo_down","transition_mtf"]', '2023-10-22T03:04:00.678Z'),
	(9, 'this-womans-work-maxwell', 17, 18, 'Sometimes a cover isn''t all that different, and I think that''s beautiful.', 'Eva', '["transition_ftm","years_apart_10"]', '2023-10-22T04:53:46.077Z'),
	(10, 'weird-fishes-lianne-la-havas', 19, 20, '', 'Eva', '["acousticness_down","transition_mtf","years_apart_10"]', '2023-10-22T04:54:39.440Z'),
	(11, 'when-you-were-mine-cyndi-lauper', 21, 22, '', 'Eva', '["transition_mtf"]', '2023-10-22T04:58:06.359Z'),
	(12, 'jolene-the-white-stripes', 23, 24, '', 'Eva', '["transition_ftm","valence_down","years_apart_20"]', '2023-10-22T04:59:43.967Z'),
	(13, 'i-wish-hatsumi-shibata', 25, 26, 'City Pop does Stevie Wonder.', 'Eva', '["transition_mtf"]', '2023-10-22T05:03:53.515Z'),
	(14, 'in-my-life-judy-collins', 27, 28, '', 'Eva', '["tempo_up","transition_mtf"]', '2023-10-22T05:07:12.305Z'),
	(15, 'i-heard-it-through-the-grapevine-the-slits', 29, 30, 'Female punk rock Marvin Gaye. Inspired.', 'Paul', '["transition_mtf","years_apart_10"]', '2023-10-22T05:08:40.674Z'),
	(16, 'how-deep-is-your-love-the-bird-and-the-bee', 31, 32, '', 'Eva', '["acousticness_up","tempo_up","transition_mtf","valence_down","years_apart_20"]', '2023-10-22T05:13:17.365Z'),
	(17, 'heart-shaped-box-amber-mark', 33, 34, 'You can just sink into this cover. The edges are still there, but they''re softer. Sweeter.', 'Eva', '["tempo_down","transition_mtf","years_apart_20"]', '2023-10-22T05:18:31.416Z'),
	(18, 'as-tears-go-by-marianne-faithfull', 35, 36, '', 'Eva', '["transition_mtf"]', '2023-10-22T05:43:19.279Z'),
	(19, 'born-this-way-orville-peck', 37, 38, 'Tambourine. Castanets. Pride. It’s all here.', 'Eva', '["transition_ftm","years_apart_10"]', '2023-10-22T05:47:07.904Z'),
	(20, 'crazy-in-love-antony-and-the-johnsons', 39, 40, 'Oboe. Harp. Strings. Anohni has transfigured this song''s pop roots into a dark, haunting beauty.', 'Eva', '["acousticness_up","energy_down","valence_down"]', '2023-10-22T05:59:05.149Z'),
	(21, 'walk-like-a-man-mary-jane-girls', 41, 42, '', 'Eva', '["transition_mtf","years_apart_30"]', '2023-10-23T06:15:16.715Z'),
	(22, 'the-night-they-drove-old-dixie-down-joan-baez', 43, 44, 'Virgil Kane is my name... like my father before me, I’m a working man.', 'Paul', '["transition_mtf"]', '2023-10-23T07:32:57.984Z'),
	(23, 'im-a-man-you-dont-meet-every-day-the-pogues', 45, 46, 'The original is a traditional Irish music hall song, but the earliest popular recording was by Jeannie Robertson.', 'Paul', '["acousticness_down"]', '2023-10-23T07:38:06.015Z'),
	(24, 'aint-no-sunshine-karen-souza', 47, 48, '', 'Eva', '["duration_up","tempo_up","transition_mtf","years_apart_40"]', '2023-10-23T07:52:55.968Z'),
